export function PostmanLogo({
  variant = "color",
  type = "icon",
  title = "Postman",
  className,
  ...props
}: PostmanLogoProps) {
  const shared = {
    height: "1em",
    ...(title ? { role: "img", "aria-label": title } : { "aria-hidden": true }),
    ...props,
  } as SVGProps<SVGSVGElement>;

  if (type === "wordmark") {
    return <Wordmark {...shared} className={className} />;
  }

  if (variant === "mono") return <IconMono {...shared} className={className} />;

  return <Icon {...shared} className={className} />;
}

export default PostmanLogo;
